queries.cql:
// CrowdStrike CQL for Real-Time Face/Voice Changer Detection During Video Interview
// Repository: flame-collaboration-video-monitoring
// Native query required - audio/video analysis cannot be expressed in Sigma
camera_driver_name=/OBS Virtual|ManyCam|DeepFace|FaceSwap|Snap Camera/i
OR audio_analysis_score>0.75
OR lip_sync_delta_ms>200
| case {
    camera_driver_name=/DeepFace|FaceSwap/i | risk_score:=90;
    camera_driver_name=/OBS Virtual|ManyCam/i | risk_score:=50;
    audio_analysis_score>0.75 | risk_score:=80;
    lip_sync_delta_ms>200 | risk_score:=70;
    * | risk_score:=0;
  }
| risk_score>=50
| groupBy([user_id, session_id], function=[count(), collect([camera_driver_name, audio_analysis_score, lip_sync_delta_ms])])
